    u = mix( u, vec3( 0.055, 0.05, 0.036 ), smoothstep( 0.6, 0.85, un.r ) * 0.5 );   // heather
    u = mix( u, vec3( 0.13, 0.12, 0.06 ), smoothstep( 0.58, 0.8, un.g ) * 0.55 );    // dry bents
